import json,shutil
from pathlib import Path
def read(p):return json.loads(Path(p).read_text(encoding='utf8'))
def main():
    human=read('reports/human_comparison_02.json');a=human['models']['pilot_01'];b=human['models']['pilot_02']
    old=read('reports/after_pilot_01.json');new=read('reports/after_pilot_02.json');run=read('runs/pilot_02/run.json');summary=read('runs/pilot_02/summary.json')
    steps=[json.loads(l) for l in Path('runs/pilot_02/metrics.jsonl').read_text().splitlines()]
    manifest=read('curriculum_v2/manifest.json');best=[r for r in steps if r.get('selected')][-1]
    if not Path('reports/comparison_01.json').exists():shutil.copy2('reports/comparison.json','reports/comparison_01.json')
    result={'available':True,'before_label':'Pilot 01','after_label':'Preview 02','parameters':20587008,'architecture_changed':False,'selected_step':b['step'],'completed_steps':summary['completed_step'],'stop_reason':summary['stop_reason'],'validation':{'before':run['baseline']['macro_loss'],'after':best['validation']['macro_loss']},'test':{'before':a['loss']['macro_loss'],'after':b['loss']['macro_loss'],'note':human['note']},'domains':[{'domain':d,'before':v['loss'],'after':b['loss']['domains'][d]['loss']} for d,v in a['loss']['domains'].items()],'math':{'before':old['math_numeric_exact'],'after':new['math_numeric_exact']},'training':summary,'tests':{'total':103,'failed':0},'data_counts':manifest['counts'],'lineage':{'init_sha256':run['source_sha256'],'export_sha256':b['checkpoint_sha256']},'limitations':['Free responses remain frequently incoherent. Lower teacher-forced loss is not proof of conversational competence.','Only 7 new German and 70 English human test pairs; exploratory evidence.','0/12 arithmetic exact-match; SOLVE is a separate tool.','No third-party checkpoints used. Human metadata and ratings are not independent factual verification.']}
    Path('reports/comparison.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8')
    lines=['# Neral Preview 02 – tatsächlich ausgeführte Arbeit','', '## Eigenes Modell bleibt erhalten','Ausschließlich die übergebenen Neral-Gewichte wurden weitertrainiert. Keine Gewichte von Qwen, Llama, ChatGPT oder anderen Modellen. Modellcode, Byte-Tokenizer und Architektur sind unverändert: **20.587.008 trainierbare Parameter**.','', 'Checkpoint-Abstammung: übergebenes Original → Pilot 01 (ausgewählt: Schritt 80) → Preview 02 (ausgewählt: Schritt 100). Das Original ist unverändert verfügbar.','', '## Daten und Training','1515 Trainingsbeispiele: bisherige 976 plus 59 deutsche und 480 englische Dialogpaare. Validation: 177 Beispiele, Test: 155. Die Ergänzung stammt aus OpenAssistant/oasst1, laut Metadaten menschlich verfasst, Apache-2.0. Es wurden ausschließlich Daten, kein Modell geladen. Revision, Prüfsummen, Lizenz und Filterregeln sind lokal gespeichert.','', 'Nur bewertete Wurzelfragen und bestplatzierte Antworten, Ausschluss markierter synthetischer Inhalte, bestimmter Qualitäts-/PII-/Sprachprobleme, erkannter sachlicher Probleme und zu langer Texte. Vollständige Antworten bis 1024 Byte-Token; keine stille Kürzung. Gesprächsbäume bleiben innerhalb eines Splits. Bewertungen garantieren keine sachliche Fehlerfreiheit.','', f'RTX 4070, BF16, AdamW, Lernrate 2e-5, effektive Batchgröße 32. Budget 400 Updates, Validierung alle 25 Updates, Early-Stopping nach vier Prüfungen ohne ausreichende Verbesserung. Tatsächlich **{summary["completed_step"]} Updates in {summary["elapsed_seconds"]:.2f} Sekunden** Trainingsschleife. Bester Stand **Schritt {b["step"]}**, spätere Updates wurden verworfen. Peak von PyTorch allokierter Speicher: {summary["peak_vram_bytes"]/2**20:.1f} MiB; nicht gesamter GPU-Speicher.', '', f'Validation-Macro-Loss über sechs Domänen: **{result["validation"]["before"]:.4f} → {result["validation"]["after"]:.4f}**. Auswahl ausschließlich anhand Validation, mit begrenzter zulässiger Verschlechterung je Domäne.', '', '## Vergleich auf Testdaten','| Domäne | Pilot 01 | Preview 02 |','|---|---:|---:|']
    lines += [f'| {r["domain"]} | {r["before"]:.4f} | {r["after"]:.4f} |' for r in result['domains']]
    lines += ['', 'Antwort-Token-Cross-Entropy, niedriger ist besser. Die vier alten Domänen sind inzwischen wiederholt betrachtete Regressionstests. Die neuen menschlichen Testdaten wurden nach dem Training verglichen; nur 7 deutsche und 70 englische Paare. Kein belastbarer allgemeiner Qualitätsbenchmark.', '', '**Freie Chat- und Codeantworten bleiben oft unverständlich. Reine Modellrechnung: weiterhin 0/12 exakt korrekt.** Der niedrigere Loss bedeutet, dass Referenzantworten wahrscheinlicher werden; er bedeutet nicht, dass Neral diese Antworten selbst zuverlässig erzeugt.', f'Alter, durch normalisierte Duplikate belasteter Verteilungs-Loss: {old["legacy"]["all_token_loss"]:.4f} → {new["legacy"]["all_token_loss"]:.4f}. Historische Baseline und erste Prüfung bleiben in ERGEBNISSE.md erhalten.', '', '## Preview und Prüfung','ChatGPT-ähnliche Bedienstruktur mit eigener Neral-Identität: schmale Gesprächsseitenleiste, neutraler dunkler/heller Hintergrund, zentrierter Startbereich, großes abgerundetes Eingabefeld, Nutzerblasen, Kopieren, Verlauf, temporäre Chats und getrennt öffnende Modellinformationen. Preview 02 ist beim Start aktiv; Original und Pilot 01 bleiben auswählbar.', '', '103 automatisierte Tests bestanden; dazu JavaScript-Syntaxprüfung. Die HTTP-Integration prüft echte Generierung aus allen drei eigenen Checkpoints sowie SOLVE, Codeprüfung und Sicherheitsregeln. Browser-Sichtprüfung ist separat in reports/browser_qa_02.json dokumentiert.', '', 'SOLVE rechnet deterministisch; Codeprüfung analysiert Python statisch. Beides ist ausdrücklich Werkzeugleistung, keine behauptete Modellfähigkeit. Prompt-Guard und kleine Security-Suite bieten keine umfassende Sicherheitsgarantie.', '', '## Start und Nachweise','Doppelklick auf START_NERAL.bat oder http://127.0.0.1:9680 öffnen. Alles zur Laufzeit lokal, keine Cloud-Inferenz.', '', '- runs/pilot_02/: vollständige Checkpoints, Optimizer-/RNG-Zustände, tatsächlich ausgeführter Trainer, Konfiguration und Messwerte.', '- export/pilot_02/: Inferenzcheckpoint und SHA-256.', '- curriculum_v2/manifest.json und ATTRIBUTION.md: Datenquellen, Lizenz, Filter und Split-Hashes.', '- reports/human_comparison_02.json und after_pilot_02.json: Verluste und unveränderte rohe Modellantworten.', '- reports/pytest.xml und live_http_02.json: ausgeführte Prüfungen.', '', 'Weitere Schritte auf demselben kleinen Korpus sind aufgrund des Early-Stoppings nicht die nächste sinnvolle Verbesserung. Neral benötigt erheblich breitere, geprüfte Sprachdaten; ein nützlicher allgemeiner Chatbot ist mit diesem Stand noch nicht erreicht.']
    Path('PREVIEW_02.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    print(json.dumps(result,ensure_ascii=True,indent=2))
if __name__=='__main__':main()
